def esc(s):return html.escape(s,quote=True)
def shot(name,caption=''):
 return f'<figure><div class="image"><img src="screenshots/{esc(name)}"></div><figcaption>{esc(caption)}</figcaption></figure>'
def page(title,kicker,body,num):
 return f'<section class="page"><header><b>fire<span>atlas</span></b><small>PRESENTATION & VISUAL POLISH GUIDE</small></header><div class="kicker">{esc(kicker)}</div><h1>{esc(title)}</h1>{body}<footer><span>27 SEPTEMBER 2026 · CURRENT IMPLEMENTATION · SCREENSHOTS FROM THE RUNNING APP</span><b>{num:02d}</b></footer></section>'
css='''@page{size:A4 landscape;margin:0}*{box-sizing:border-box}html,body{margin:0;background:#0b1219;color:#e6eeed;font-family:Arial,sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact}.page{width:297mm;height:210mm;padding:12mm 14mm;position:relative;page-break-after:always;overflow:hidden;background:radial-gradient(ellipse at 95% 0,#203637 0,transparent 55%),#0b1219}.page:last-child{page-break-after:auto}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #33484e;padding-bottom:9px;margin-bottom:16px}header>b{font-size:21px;letter-spacing:-1px;color:#f4ac7f}header>b span{color:#ccd7d6}header small{font-size:8px;letter-spacing:2px;color:#94aeb9}.kicker{font-size:9px;letter-spacing:1.5px;color:#8fd1c3;margin-bottom:7px}h1{font-size:30px;font-weight:500;letter-spacing:-1px;line-height:1.12;margin:0 0 14px}h2{font-size:15px;color:#f2bb98;font-weight:500;margin:0 0 7px}h3{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#8fd1c3;margin:14px 0 7px}p,li{font-size:11px;line-height:1.52;color:#bfced2;margin:0 0 9px}strong{color:#f0e9de}a{color:#a9dfd3;text-decoration:none}.columns{display:grid;grid-template-columns:61% 36%;gap:3%;align-items:start}figure{margin:0;border:1px solid #395057;border-radius:8px;overflow:hidden;background:#070d11}.image{height:111mm;padding:7px;display:flex;align-items:center;justify-content:center}.image img{max-width:100%;max-height:100%;object-fit:contain}figcaption{font-size:8px;line-height:1.5;color:#97adb8;padding:9px 11px;border-top:1px solid #243941}.route{margin-top:12px;padding:11px;background:#12242a;border-radius:6px;overflow-wrap:anywhere;font-size:9px;line-height:1.6}.route b{display:block;color:#efbd9a;font-size:9px;letter-spacing:1px}.aside ul{padding-left:16px;margin:0}.aside li{margin-bottom:6px}.check{border-left:2px solid #89caba;padding:7px 10px;background:#16272c}.limit{font-size:9px;line-height:1.5;color:#92a9b6;margin-top:11px}.caption{font-size:9px;color:#96aeba}.lead{font-size:16px;line-height:1.55;max-width:750px}footer{position:absolute;bottom:10mm;left:14mm;right:14mm;display:flex;justify-content:space-between;border-top:1px solid #31454b;padding-top:8px;font-size:7px;letter-spacing:1px;color:#7895a3}footer b{font-size:11px;color:#ffbb91}.cover-grid{display:grid;grid-template-columns:34% 63%;gap:3%}.cover-grid figure .image{height:119mm}.cover-grid h2{font-size:29px;line-height:1.2;margin:10px 0 20px}.cover-grid p{font-size:13px}.pill{display:inline-block;padding:6px 9px;border:1px solid #50766f;border-radius:20px;color:#b6dbd0;font-size:9px;margin:4px 4px 12px 0}table{border-collapse:collapse;width:100%;font-size:10px}td,th{padding:8px 10px;text-align:left;border-bottom:1px solid #30434c;line-height:1.35}th{color:#9ad3c7;font-size:9px;letter-spacing:1px}td{color:#c5d4d8}tr:nth-child(even){background:#ffffff03}.two{display:grid;grid-template-columns:1fr 1fr;gap:25px}.box{padding:17px;border:1px solid #39545b;border-radius:8px;background:#112027}.box h2{font-size:21px}.box li{font-size:12px}.phone .image{height:117mm}.phone-grid{display:grid;grid-template-columns:26% 26% 44%;gap:2%}.big{font-size:30px;color:#ffb78b;margin:8px 0}.script li{font-size:13px;margin-bottom:13px}.small{font-size:10px}'''
pages=[]
pages.append(page('From working features to a memorable presentation.','FIREATLAS / A FEATURE-BY-FEATURE POLISH PLAN',f'''<div class="cover-grid"><div><span class="pill">16 FEATURE PRIORITIES</span><span class="pill">EXACT PAGES + REAL IMAGES</span><h2>Polish one visible story at a time.</h2><p>This guide inventories the project’s strongest implemented features and gives each a concrete presentation target.</p><p>Use the page order as a work queue. Finish the interaction and its explanation before moving to the next feature.</p><p class="limit">“Standout” means valuable within this project. It does not claim that these capabilities are unique in the wider wildfire software market.</p><p class="limit">Screenshots show the current app. Improvements listed in this guide are recommendations, not completed redesigns.</p></div>{shot('01-globe.png','Authentic NASA observations on the landing globe. Current desktop screenshot.')}</div>''',1))
rows=''.join(f'<tr><td>{i:02d}</td><td><a href="#feature-{i}">{esc(f[0])}</a></td><td>{i+2:02d}</td><td>{"First impression / core explanation" if i<=5 else "Depth / interactive proof" if i<=11 else "Supporting polish"}</td></tr>' for i,f in enumerate(features,1))
pages.append(page('The order to work in.','POLISH ROADMAP / FINISH EACH READY-TO-PRESENT CHECK',f'<table><thead><tr><th>ORDER</th><th>FEATURE</th><th>PDF PAGE</th><th>PRESENTATION ROLE</th></tr></thead><tbody>{rows}</tbody></table>',2))
for i,(title,img,kind,route,action,why,improvements,done,limit) in enumerate(features,1):
 body=f'''<div id="feature-{i}" class="columns"><div>{shot(img,kind+' · Actual current interface.')}<div class="route"><b>EXACT PAGE / OPEN THIS VIEW</b><a href="{esc(BASE+route)}">{esc(BASE+route)}</a><br><strong>Interaction:</strong> {esc(action)}</div></div><div class="aside"><h2>Why it stands out</h2><p>{esc(why)}</p><h3>Beautify next</h3><ul>{''.join('<li>'+esc(x)+'</li>' for x in improvements)}</ul><h3>Ready to present when</h3><p class="check">{esc(done)}</p><p class="limit">{esc(limit)}</p></div></div>'''
 pages.append(page(title,f'PRIORITY {i:02d} / {kind}',body,i+2))
num=len(pages)+1
pages.append(page('What is the mobile app today?','APP STATUS / PRESENTATION FORMAT',f'''<div class="phone-grid"><div class="phone">{shot('18-mobile-globe.png','Mobile globe · 390 px touch-browser emulation.')}</div><div class="phone">{shot('19-mobile-crew.png','Crew Device · fictional Bravo exercise.')}</div><div><h2>Now: an installable mobile web app.</h2><p>The responsive website already provided the globe, atlas, research tools and Crew Device exercise. This update adds a web-app manifest, icons, standalone launch, installation instructions and an explicit offline reconnect screen.</p><h3>Functional browser checks</h3><p>Mobile crew selection, replay, prepared-tab offline reload, saved time/crew restoration and offline exercise export passed. The narrower Training Lab worker continues to own its offline behavior.</p><h3>Not a native app release</h3><p>No Android APK or iOS native project exists. No real device GPS, push alerts, background tracking or shared commander/crew sessions are implemented.</p><p class="check">Phone presentation: use a reachable HTTPS deployment, install it from the phone’s browser, and rehearse on that physical phone.</p><p class="limit">Browser emulation and installability validation are not a physical-device installation test. The globe and analysis tools still require the application server.</p><div class="route"><a href="{BASE}/install.html">{BASE}/install.html</a></div></div></div>''',num))
num+=1
pages.append(page('Get the phone ready before rehearsal.','MOBILE SETUP / NO SURPRISES ON STAGE',f'''<div class="two"><div class="box"><h2>1. Reach the same dataset</h2><p>Deploy the Python application and its database at a trusted HTTPS address reachable by the phone. A GitHub repository is not the running backend.</p><p>Copy the populated local database or import the original NASA CSVs on that host. A fresh checkout includes the NOAA sample and synthetic seeds; it does not include the 866,956 recent global NASA records.</p><p><strong>Do not open localhost:8000 on the phone.</strong> That points to the phone itself. For an online LAN-only preview, run the server with <code>--host 0.0.0.0</code> on a trusted network and use the laptop’s LAN address. Plain HTTP LAN access does not provide secure PWA installation or offline service workers.</p><h3>2. Install from the browser</h3><p>Android Chrome: menu → Install app / Add to Home screen.<br>iPhone Safari: Share → Add to Home Screen → Open as Web App if offered.</p><p><a href="https://developer.mozilla.org/en-US/docs/Web/Progressive_web_apps/Guides/Making_PWAs_installable">MDN: installation requirements</a> · <a href="https://support.apple.com/guide/iphone/iphea86e5236/ios">Apple: home-screen instructions</a></p></div><div class="box"><h2>3. Prepare the offline demonstration</h2><ol><li>Open Training Lab while connected.</li><li>Wait for <strong>Offline page ready</strong> and <strong>Progress saved in this tab</strong>.</li><li>Advance to 12:05, choose Crew Bravo and keep this tab open.</li><li>Disconnect, reload the same tab and show the saved clock plus disconnected status.</li><li>Export the exercise record offline, reconnect and resume.</li></ol><h3>4. Check the actual phone</h3><p>Confirm readable controls, touch rotation, satellite filtering, crew selection, browser downloads, installation and same-tab offline recovery.</p><p class="check">No public HTTPS deployment or physical-phone test was completed during this documentation task. Those are the remaining setup gates for presenting from a separate phone.</p></div></div>''',num))
num+=1
pages.append(page('A five-minute presentation path.','PRESENTER SCRIPT / DEMONSTRATE CAUSE AND EFFECT',f'''<div class="two"><div class="box"><ol class="script"><li><strong>0:00–0:45 · Earth.</strong> Rotate the globe, point out the imported snapshot date, select one cluster and inspect its evidence.</li><li><strong>0:45–1:45 · Calendar + sensors.</strong> Open the September 2026 synthetic showcase. Show the seasonal peak, three-year baseline and MODIS / VIIRS / Joint comparison.</li><li><strong>1:45–2:15 · Traceability.</strong> Open a detected day, expand a record, then show Download study. Explain how exported inputs reproduce the counts.</li></ol></div><div class="box"><ol class="script" start="4"><li><strong>2:15–3:15 · Research.</strong> Show the overlap chart, three candidate groups and the synthetic exposure mask. Clear the mask to demonstrate why unknown coverage matters.</li><li><strong>3:15–4:30 · Mobile crew.</strong> Open the fictional Crew Device view, advance the replay and demonstrate the disconnection drill or prepared-tab offline reload.</li><li><strong>4:30–5:00 · Close with evidence.</strong> Return to Data Sources. State which inputs are authentic, which are synthetic, and the next visual improvement.</li></ol></div></div><p class="lead" style="margin-top:20px">The strongest story is: <strong>see a signal → compare fairly → inspect the evidence → rehearse a decision.</strong></p><p class="limit">Keep SAR, calibrated sensitivity, operational spread forecasts and real crew tracking off the feature demo until implemented and validated. They are future requirements, not available capabilities.</p>''',num))
num+=1
pages.append(page('What was checked—and what remains.','READINESS RECORD / USE ACCURATE PRESENTATION CLAIMS',f'''<div class="two"><div class="box"><h2>Verified in this workspace</h2><ul><li>Current globe: 866,956 authentic NASA detections, 7,307 one-degree display clusters.</li><li>Authentic database: 916,376 observations including the NOAA historical slice.</li><li>Separate full-year synthetic showcase: 11,322 records across 96 source-months.</li><li>All 56 automated tests and the application build passed after the mobile-app addition.</li><li>Fresh desktop and mobile screenshots were captured for this guide.</li><li>Mobile browser checks covered offline launch, training-worker ownership, same-tab reload, saved crew/clock and offline export.</li></ul><p class="limit">The matching code verification log and screenshot manifest accompany this guide. These checks verify application behavior, not scientific validity or real-world crew safety.</p></div><div class="box"><h2>Still requires a real input or deployment</h2><ul><li>A trusted HTTPS host reachable from the presentation phone, with the intended database loaded.</li><li>A rehearsal on the actual Android/iPhone and browser.</li><li>Native packaging if an APK or iOS build is specifically required.</li><li>Real pass/cloud masks, measured weather, validated SAR analysis and calibrated spread models for scientific claims.</li><li>Real cross-device sessions, permissions, GPS and background delivery for operational crew use.</li></ul><h3>Useful project references</h3><p>PRD.md · docs/DATA_READINESS.md · docs/GLOBE_OBSERVATIONS.md · docs/RESEARCH_METHODS.md</p><p><a href="{BASE}/data.html">Open Data Sources</a> · <a href="{BASE}/install.html">Open mobile setup</a></p></div></div><p class="caption" style="margin-top:16px">All page links use the current local server. Replace http://127.0.0.1:8000 with the presentation host when sharing with another device. Screenshots and captions identify synthetic, authentic and fictional content.</p>''',num))
html_path=OUT/'FireAtlas_Feature_Polish_Guide.html'
html_path.write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><title>FireAtlas — Feature Polish & Mobile Presentation Guide</title><style>'+css+'</style></head><body>'+''.join(pages)+'</body></html>')
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/google-chrome',headless=True)
 page=browser.new_page(viewport={"width":1123,"height":794})
 page.goto(html_path.as_uri(),wait_until='load')
 page.evaluate('document.fonts.ready')
 missing=page.locator('img').evaluate_all('(images)=>images.filter(i=>!i.complete||i.naturalWidth===0).map(i=>i.src)')
 if missing:raise RuntimeError(f'Missing screenshots: {missing}')
 overlaps=page.locator('.page').evaluate_all('''pages => pages.flatMap((p,i) => { const footer=p.querySelector('footer').getBoundingClientRect(); return [...p.querySelectorAll('p,li,figure,.route,table,.box')].filter(e => e.getBoundingClientRect().bottom > footer.top - 4).map(e => ({page:i+1,tag:e.tagName,text:e.textContent.slice(0,80)})); })''')
 if overlaps:raise RuntimeError(f'Content overlaps footer: {overlaps}')
 page.pdf(path=str(OUT/'FireAtlas_Feature_Polish_Guide.pdf'),format='A4',landscape=True,print_background=True,prefer_css_page_size=True,tagged=True)
 page.screenshot(path=str(OUT/'guide-cover.png'),full_page=False)
 browser.close()
print(f'Built {len(pages)} pages: {OUT}/FireAtlas_Feature_Polish_Guide.pdf')
